<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {useRouter} from 'vue-router'
import Panel from '../components/Panel.vue'
import {api,busy,current,error,notify,refresh,run,select} from '../store'
interface Glyph {char:string;box:[number,number,number,number];polarity:'zhu'|'bai'|'black';mirrored:boolean;reviewed:boolean}
const state=ref<any>(null),style=ref('待归类'),annotator=ref(localStorage.getItem('yinmai-annotator')||''),notes=ref('')
const glyphs=ref<Glyph[]>([]),canvas=ref<HTMLCanvasElement>(),drawing=ref(false),draftBox=ref<number[]|null>(null)
const segLayout=ref('auto'),segPolarity=ref('auto'),proposal=ref<any>(null),proposalId=ref<string|null>(null),pendingProposalId=ref<string|null>(null)
const selectedBox=ref(-1),imageSize=ref<[number,number]>([1,1])
const selectedGlyph=computed(()=>glyphs.value[selectedBox.value])
const dirty=ref(false),loading=ref(false),confirmOpen=ref(false)
const modelId=ref(''),text=ref('印脉重生'),result=ref<any>(null)
const original=computed(()=>current.value?.artifacts.find(a=>a.kind==='original'))
const models=computed<any[]>(()=>state.value?.models||[]),chosenModel=computed(()=>models.value.find(m=>m.id===modelId.value))
const reviewed=computed(()=>glyphs.value.filter(g=>g.reviewed).length)
const styleData=computed(()=>state.value?.styles.find((s:any)=>s.style===style.value))
let startPoint:[number,number]|null=null,version=0,restore=false
let resolveDiscard:((value:boolean)=>void)|null=null,pendingDiscard:Promise<boolean>|null=null
function confirmDiscard(){if(!dirty.value)return Promise.resolve(true);if(pendingDiscard)return pendingDiscard;confirmOpen.value=true;pendingDiscard=new Promise<boolean>(resolve=>resolveDiscard=resolve);return pendingDiscard}
function decideDiscard(value:boolean){confirmOpen.value=false;resolveDiscard?.(value);resolveDiscard=null;pendingDiscard=null}
const removeGuard=useRouter().beforeEach(()=>confirmDiscard())
function changed(){dirty.value=true;paint()}
function invalidate(g:Glyph){g.reviewed=false;changed()}
function changeStyle(){glyphs.value.forEach(g=>g.reviewed=false);changed()}
function paint(){const c=canvas.value;if(!c)return;const ctx=c.getContext('2d');if(!ctx)return;ctx.clearRect(0,0,c.width,c.height);ctx.font=`bold ${Math.max(12,c.width*.055)}px sans-serif`;ctx.lineWidth=Math.max(1,c.width*.007)
 const draw=(b:number[],label:string,color:string)=>{ctx.strokeStyle=color;ctx.fillStyle=color;ctx.strokeRect(b[0]*c.width,b[1]*c.height,(b[2]-b[0])*c.width,(b[3]-b[1])*c.height);ctx.fillText(label,b[0]*c.width+3,Math.max(16,b[1]*c.height+20))}
 glyphs.value.forEach((g,i)=>draw(g.box,`${i+1} ${g.char||'待释文'}`,i===selectedBox.value?'#f0ac34':g.reviewed?'#15836b':'#006ca3'));if(draftBox.value)draw(draftBox.value,'框选中','#ffb000')}
function imageLoaded(e:Event){const im=e.target as HTMLImageElement;imageSize.value=[im.naturalWidth,im.naturalHeight];if(canvas.value){canvas.value.width=im.naturalWidth;canvas.value.height=im.naturalHeight;paint()}}
function point(e:PointerEvent):[number,number]{const b=canvas.value!.getBoundingClientRect();return [Math.max(0,Math.min(1,(e.clientX-b.left)/b.width)),Math.max(0,Math.min(1,(e.clientY-b.top)/b.height))]}
function start(e:PointerEvent){if(!drawing.value||loading.value||busy.value||glyphs.value.length>=64)return;e.preventDefault();canvas.value!.setPointerCapture(e.pointerId);startPoint=point(e);draftBox.value=[...startPoint,...startPoint];paint()}
function move(e:PointerEvent){if(!startPoint)return;const p=point(e);draftBox.value=[Math.min(startPoint[0],p[0]),Math.min(startPoint[1],p[1]),Math.max(startPoint[0],p[0]),Math.max(startPoint[1],p[1])];paint()}
function stop(){if(startPoint&&draftBox.value){const b=draftBox.value as Glyph['box'];if((b[2]-b[0])*canvas.value!.width>=8&&(b[3]-b[1])*canvas.value!.height>=8){glyphs.value.push({char:'',box:b,polarity:'zhu',mirrored:false,reviewed:false});dirty.value=true}}startPoint=null;draftBox.value=null;paint()}
function cancel(){startPoint=null;draftBox.value=null;paint()}
function remove(index:number){glyphs.value.splice(index,1);changed()}
function chooseBox(index:number){selectedBox.value=index;paint()}
function editCoordinate(coordinate:number,e:Event){const g=selectedGlyph.value;if(!g)return;const value=Number((e.target as HTMLInputElement).value)/100;const b=[...g.box] as Glyph['box'];b[coordinate]=value;if(!Number.isFinite(value)||value<0||value>1||(b[2]-b[0])*imageSize.value[0]<8||(b[3]-b[1])*imageSize.value[1]<8){error.value='字框须位于原图内，且至少8×8像素';(e.target as HTMLInputElement).value=(g.box[coordinate]*100).toFixed(1);return}g.box=b;invalidate(g)}
function useProposal(){if(!proposal.value)return;glyphs.value=proposal.value.glyphs.map((g:Glyph)=>({char:'',box:[...g.box],polarity:g.polarity,mirrored:false,reviewed:false}));proposalId.value=pendingProposalId.value;selectedBox.value=glyphs.value.length?0:-1;drawing.value=false;cancel();dirty.value=true;paint()}
async function autoSegment(){await run(async()=>{if(!current.value||!original.value)throw new Error('先选择原始印谱');const r=await api(`/seals/${current.value.id}/segment-glyphs`,{method:'POST',body:JSON.stringify({source_artifact_id:original.value.id,source_sha256:original.value.metadata.sha256,layout:segLayout.value,polarity:segPolarity.value})});proposal.value=r.result;pendingProposalId.value=r.artifact.id;if(!glyphs.value.length&&r.result.glyphs.length)useProposal();notify(r.result.glyphs.length?`已建议 ${r.result.glyphs.length} 个候选框，释文留空，请核对边界。`:'未找到适合的候选框，请调整模式或手动框选。')})}
async function loadStatus(){state.value=await api('/font/status')}
async function save(){await run(async()=>{if(!current.value||!original.value)throw new Error('先载入原稿');if(glyphs.value.some(g=>g.reviewed&&Array.from(g.char).length!==1))throw new Error('勾选已核对的字必须填写一个汉字');const r=await api(`/seals/${current.value.id}/glyphs`,{method:'POST',body:JSON.stringify({source_artifact_id:original.value.id,source_sha256:original.value.metadata.sha256,style:style.value,annotator:annotator.value,notes:notes.value,proposal_artifact_id:proposalId.value,glyphs:glyphs.value})});dirty.value=false;localStorage.setItem('yinmai-annotator',annotator.value);await loadStatus();notify(`已保存 ${r.document.glyphs.length} 个单字框；只有勾选核对的字进入导出。`)})}
async function download(){await run(async()=>{if(dirty.value)throw new Error('请先保存单字标注');const response=await fetch('/api/font/dataset.zip?style='+encodeURIComponent(style.value));if(!response.ok){const e=await response.json();throw new Error(e.detail)}const url=URL.createObjectURL(await response.blob());const a=document.createElement('a');a.href=url;a.download='yinmai-font-dataset.zip';a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);notify('字形样本已导出。解压后用字体训练入口开始GPU训练。')})}
async function generate(){await run(async()=>{result.value=await api('/font/generate',{method:'POST',body:JSON.stringify({model_id:modelId.value,text:text.value})});await refresh();notify('已实际执行字形模型，结果与模型来源已归档。')})}
watch(()=>current.value?.id,async(id,previous)=>{if(restore){restore=false;return}if(!(await confirmDiscard())){restore=true;select(previous||'__reference__');return}const v=++version;glyphs.value=[];proposal.value=null;proposalId.value=null;pendingProposalId.value=null;selectedBox.value=-1;dirty.value=false;cancel();if(!id)return;loading.value=true;try{const r=await api(`/seals/${id}/glyphs/latest`);if(v!==version)return;if(r.document){const d=r.document;style.value=d.style;annotator.value=d.annotator;notes.value=d.notes;glyphs.value=d.glyphs;proposalId.value=d.proposal_artifact_id||null}await nextTick();paint()}catch(e){error.value=e instanceof Error?e.message:'读取字形标注失败'}finally{if(v===version)loading.value=false}},{immediate:true})
function beforeUnload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue=''}}
onMounted(async()=>{window.addEventListener('beforeunload',beforeUnload);try{await loadStatus()}catch(e){error.value=e instanceof Error?e.message:'工坊加载失败'}})
onBeforeUnmount(()=>{removeGuard();decideDiscard(false);window.removeEventListener('beforeunload',beforeUnload)})
</script>
<template>
<div class="font-brief"><div><span class="pill">印谱风格学习</span><h2>让指定的字，延续印谱的笔意。</h2><p>单字框选与释文 → 同风格字形训练 → 输入文字生成。字形输出为图片，尚未导出可安装字体。</p></div><RouterLink to="/lab" class="button small">载入印谱素材</RouterLink></div>
<div class="font-status"><div><b>{{state?.styles.reduce((n:number,s:any)=>n+s.reviewed,0)||0}}</b><span>已核对的印谱单字</span></div><div><b>{{state?.styles.filter((s:any)=>!s.unclassified).length||0}}</b><span>人工风格分组</span></div><div><b>{{models.filter(m=>!m.demo_only).length}}</b><span>印谱风格模型</span></div><p>{{state?.seal_model_available?'已接入印谱实验模型，请核对生成笔画。':'印谱风格尚待训练。已有去噪权重不能生成指定汉字。'}}</p></div>
<div class="font-columns"><Panel title="01 · 自动分割与单字核对" note="自动候选 · 原稿保留">
<div class="font-segment-controls"><label>印文布局<select v-model="segLayout" aria-label="自动分割布局"><option value="auto">自动判断行列</option><option value="1x1">保留整印候选</option><option value="1x2">1行2列</option><option value="1x3">1行3列</option><option value="1x4">1行4列</option><option value="2x1">2行1列</option><option value="3x1">3行1列</option><option value="4x1">4行1列</option><option value="2x2">2行2列</option><option value="2x3">2行3列</option><option value="3x2">3行2列</option><option value="3x3">3行3列</option><option value="4x2">4行2列</option><option value="2x4">2行4列</option><option value="3x4">3行4列</option><option value="4x3">4行3列</option><option value="4x4">4行4列</option></select></label><label>印迹类型<select v-model="segPolarity" aria-label="自动分割朱白文"><option value="auto">自动建议朱白文</option><option value="zhu">朱文（红色字）</option><option value="bai">白文（白色字）</option><option value="black">黑色字迹</option></select></label></div>
<button class="primary full" :disabled="busy||loading||!original" @click="autoSegment">自动分割候选字形</button>
<div v-if="proposal" class="font-segment-result" role="status"><b>{{proposal.glyphs.length}} 个候选 · {{proposal.layout||'未确定布局'}} · 待核对</b><p v-for="warning in proposal.warnings" :key="warning">{{warning}}</p><button v-if="glyphs.length&&proposal.glyphs.length" :disabled="busy" @click="useProposal">用本次候选替换当前字框</button><small>替换只修改当前草稿；已保存的标注版本保留。</small></div>
<template v-if="original"><p class="hint">当前：{{current?.filename}}。一个框只含一个字，避开边框；白文需框在印面内部。不确定的释文请留待考证。</p><div class="font-canvas" :class="{drawing}"><img :src="original.url" alt="用于框选单字的印谱原稿" @load="imageLoaded"><canvas ref="canvas" aria-label="拖动框选单个印文字形" @pointerdown="start" @pointermove="move" @pointerup="stop" @pointercancel="cancel" @lostpointercapture="cancel"/></div><label class="font-check"><input type="checkbox" v-model="drawing" :disabled="busy||loading">启用单字框选</label></template>
<div v-else class="empty-state">请先在顶部选择原稿，或<RouterLink to="/lab">从印谱素材载入</RouterLink>。</div>
<div class="font-fields"><label>风格分组<input v-model="style" maxlength="80" placeholder="同一印人或明确字形风格" @input="changeStyle"></label><label>标注人<input v-model="annotator" maxlength="80" @input="changed"></label></div>
<p class="hint">同一本印谱可能收录多位印人；请按字形风格分组，不把所有图片自动视作一种字体。</p>
<div v-if="selectedGlyph" class="font-box-editor"><b>调整第 {{selectedBox+1}} 个框</b><div><label v-for="(label,k) in ['左','上','右','下']" :key="label">{{label}} %<input type="number" :aria-label="`字框${label}边界百分比`" min="0" max="100" step="0.1" :value="(selectedGlyph.box[k]!*100).toFixed(1)" @change="editCoordinate(k,$event)"></label></div><p class="hint">修改框、朱白文或释文会清除该字的核对标记。</p></div>
<div class="font-glyph-list"><div v-for="(g,i) in glyphs" :key="i" class="font-glyph-row"><button class="font-box-select" :aria-label="`选择第${i+1}个字框`" @click="chooseBox(i)">{{i+1}}</button><svg v-if="original" class="font-glyph-thumb" :viewBox="`${g.box[0]*imageSize[0]} ${g.box[1]*imageSize[1]} ${(g.box[2]-g.box[0])*imageSize[0]} ${(g.box[3]-g.box[1])*imageSize[1]}`" role="img" :aria-label="`第${i+1}个候选字形`"><image :href="original.url" :width="imageSize[0]" :height="imageSize[1]"/></svg><input v-model="g.char" :aria-label="`第${i+1}框对应汉字`" placeholder="待释文" @focus="chooseBox(i)" @input="invalidate(g)"><select v-model="g.polarity" :aria-label="`第${i+1}框朱白文`" @change="invalidate(g)"><option value="zhu">朱文</option><option value="bai">白文</option><option value="black">黑色字迹</option></select><label><input type="checkbox" v-model="g.mirrored" @change="invalidate(g)">镜像</label><label><input type="checkbox" v-model="g.reviewed" :disabled="Array.from(g.char).length!==1" @change="changed">已核对</label><button :aria-label="`删除第${i+1}个字框`" @click="remove(i)">×</button></div></div>
<p v-if="!glyphs.length" class="hint">尚无候选框，可自动分割或手动框选；系统不会猜测篆字释文。</p><label class="lab-field">备注<textarea v-model="notes" maxlength="3000" rows="2" @input="changed"/></label>
<button class="primary full" :disabled="busy||loading||!original||!annotator.trim()" @click="save">保存单字标注 · 已核对 {{reviewed}} / {{glyphs.length}}</button>
</Panel><div class="font-right"><Panel title="02 · 训练一种风格" note="独立于去噪训练">
<p>按对应汉字配对内容字形与印谱字形，让模型学习这一组字的笔画与布局特征。</p><dl class="data-list compact"><div><dt>当前风格</dt><dd>{{style}}</dd></div><div><dt>已核对样本</dt><dd>{{styleData?.reviewed||0}} 个</dd></div><div><dt>不同汉字</dt><dd>{{styleData?.characters||0}} 字</dd></div></dl><button class="full" :disabled="busy||!styleData?.reviewed||styleData?.unclassified||dirty" @click="download">导出当前风格的训练字形</button><p class="hint">解压样本包，双击项目中的 Start-Font-Training.cmd。按提示填写样本目录；训练完成后刷新本页选择模型。</p><p class="hint">基线入口至少需要32个训练字、8个验证字、8个测试字，按汉字隔离。这个下限只保证流程可运行，生成质量仍需逐字检查。</p>
</Panel><Panel title="03 · 输入文字生成" note="实际模型推理">
<label class="lab-field">字形模型<select v-model="modelId" aria-label="字形生成模型"><option value="">选择已训练的风格</option><option v-for="m in models" :key="m.id" :value="m.id">{{m.style}}{{m.demo_only?' · 非印谱':''}}</option></select></label><p v-if="chosenModel?.demo_only" class="font-demo-note">这是本机字体之间的训练流程验证，用于检查生成链路。没有学过这批印谱。</p><label class="lab-field">生成文字<input v-model="text" maxlength="12" aria-label="需要生成的汉字" placeholder="印脉重生"></label><button class="primary full" :disabled="busy||!modelId||!text.trim()" @click="generate">生成指定字形</button>
<figure v-if="result" class="font-output"><img :src="result.artifact.url" :alt="`模型实际生成的${result.artifact.metadata.text}`"><figcaption>{{result.artifact.metadata.demo_only?'本机字体流程验证 · 非印谱风格':'印谱风格实验结果 · 需人工核对'}}<a :href="result.artifact.url" download="generated-glyphs.png">下载图片</a></figcaption></figure><p class="hint">生成笔画未作历史考证；生僻篆字可能变形或写错。当前输出为字形图片，后续可经人工校订、矢量化后制作字体文件。</p><button class="full" :disabled="busy" @click="loadStatus">刷新标注统计与模型</button>
</Panel></div></div>
<div v-if="confirmOpen" class="lab-discard-overlay" role="dialog" aria-modal="true" aria-labelledby="font-discard-title"><div class="lab-discard-dialog"><h3 id="font-discard-title">字形标注尚未保存</h3><p>离开会丢失刚才的字框和释文。</p><div><button @click="decideDiscard(false)">继续标注</button><button class="primary" @click="decideDiscard(true)">放弃修改并离开</button></div></div></div>
</template>
